import type { BoardData, ItemDetail, ItemRecord, ItemUpdate } from './types';

/**
 * Data layer.
 *
 * List: the stopgap service has no JSON list endpoint, so the board list
 * comes from a snapshot generated by scripts/snapshot-board.py (same
 * queries the stopgap renders from). P5 (TRK-0273) replaces this with a
 * real GET /api/board.
 *
 * Detail + edits: LIVE against the real service endpoints
 * (GET /api/item/<id>, POST /api/item/<id>/update), reached through the
 * Vite proxy (see vite.config.ts). Writes carry the same server-side
 * whitelist + validation as the stopgap page.
 */

export async function loadBoard(): Promise<BoardData> {
  const res = await fetch('/board-data.json', { cache: 'no-store' });
  if (!res.ok) throw new Error(`board snapshot failed: ${res.status}`);
  return (await res.json()) as BoardData;
}

export async function fetchItem(id: string): Promise<ItemDetail> {
  const res = await fetch(`/api/item/${encodeURIComponent(id)}`);
  const json = await res.json().catch(() => null);
  if (!res.ok || !json) {
    throw new Error(json?.error ?? `item fetch failed: ${res.status}`);
  }
  return json as ItemDetail;
}

export async function updateItem(id: string, fields: ItemUpdate): Promise<ItemRecord> {
  const res = await fetch(`/api/item/${encodeURIComponent(id)}/update`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(fields),
  });
  const json = await res.json().catch(() => null);
  if (!res.ok || !json?.ok) {
    throw new Error(json?.error ?? `save failed: ${res.status}`);
  }
  return json.item as ItemRecord;
}
